function sma(arr, n) {
  if (arr.length < n) return null;
  const slice = arr.slice(-n);
  return slice.reduce((a, b) => a + b, 0) / n;
}

function rsi(values, period = 14) {
  if (values.length <= period) return null;
  let gains = 0, losses = 0;
  for (let i = 1; i <= period; i++) {
    const d = values[i] - values[i - 1];
    if (d >= 0) gains += d; else losses -= d;
  }
  let avgGain = gains / period, avgLoss = losses / period;
  for (let i = period + 1; i < values.length; i++) {
    const d = values[i] - values[i - 1];
    avgGain = (avgGain * (period - 1) + Math.max(d, 0)) / period;
    avgLoss = (avgLoss * (period - 1) + Math.max(-d, 0)) / period;
  }
  if (avgLoss === 0) return 100;
  return 100 - 100 / (1 + avgGain / avgLoss);
}

const out = [];
for (const item of $input.all()) {
  const data = item.json;
  const series = data['Time Series (Daily)'];
  if (!series) {
    out.push({ json: {
      ticker: data['Meta Data']?.['2. Symbol'] ?? 'UNKNOWN',
      error: data['Information'] || data['Note'] || data['Error Message'] || 'No data'
    }});
    continue;
  }

  const ticker = data['Meta Data']['2. Symbol'];
  const dates = Object.keys(series).sort();          // oldest first
  const closes = dates.map(d => parseFloat(series[d]['4. close']));
  const volumes = dates.map(d => parseFloat(series[d]['5. volume']));

  const sma20 = sma(closes, 20), sma50 = sma(closes, 50);
  const prev = closes.slice(0, -1);
  const sma20Prev = sma(prev, 20), sma50Prev = sma(prev, 50);
  const rsi14 = rsi(closes, 14);
  const avgVol20 = sma(volumes.slice(0, -1), 20);
  const volRatio = avgVol20 ? volumes[volumes.length - 1] / avgVol20 : null;

  const signals = [];
  if (sma20 && sma50 && sma20Prev && sma50Prev) {
    if (sma20Prev <= sma50Prev && sma20 > sma50) signals.push('golden_cross');
    if (sma20Prev >= sma50Prev && sma20 < sma50) signals.push('death_cross');
  }
  if (rsi14 !== null && rsi14 < 30) signals.push('rsi_oversold');
  if (rsi14 !== null && rsi14 > 70) signals.push('rsi_overbought');
  if (volRatio !== null && volRatio > 1.5) signals.push('volume_spike');

  out.push({ json: {
    ticker,
    date: dates[dates.length - 1],
    close: closes[closes.length - 1],
    sma20: sma20 && +sma20.toFixed(2),
    sma50: sma50 && +sma50.toFixed(2),
    rsi14: rsi14 !== null ? +rsi14.toFixed(1) : null,
    volume_ratio: volRatio && +volRatio.toFixed(2),
    signals,
    signal_count: signals.length
  }});
}
return out;
